Problem:
A clothing manufacturing company needs to transport their product by cargo ship or airplane. A cargo ship can transport 40 units per trip while by airplane can transport 60 units per trip. A cargo ship produces 20 units of pollution and an airplane produces 35 units of pollution. There can be at least 6 airplane trips made and at least 25% of all trips must be made by cargo ship. The company needs to transport at least 750 units of their product. How many of each transportation should they use to minimize the total amount of pollution produced?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "cargo ship trips",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "airplane trips",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "cargo ship trips",
     "coef": 20.0
    },
    {
     "var": "airplane trips",
     "coef": 35.0
    }
   ]
  },
  "constraints": [
   {
    "name": "minimum airplane trips",
    "terms": [
     {
      "var": "airplane trips",
      "coef": 1.0
     }
    ],
    "sense": ">=",
    "rhs": 6.0
   },
   {
    "name": "ship share of all trips",
    "terms": [
     {
      "var": "cargo ship trips",
      "coef": 0.75
     },
     {
      "var": "airplane trips",
      "coef": -0.25
     }
    ],
    "sense": ">=",
    "rhs": 0.0
   },
   {
    "name": "units transported",
    "terms": [
     {
      "var": "cargo ship trips",
      "coef": 40.0
     },
     {
      "var": "airplane trips",
      "coef": 60.0
     }
    ],
    "sense": ">=",
    "rhs": 750.0
   }
  ]
 },
 "facts": {
  "objective": 410.0,
  "values": {
   "cargo ship trips": 10.0,
   "airplane trips": 6.0
  },
  "binding": [
   "minimum airplane trips"
  ],
  "slack": {
   "minimum airplane trips": 0.0,
   "ship share of all trips": 6.0,
   "units transported": 10.0
  },
  "shadow_prices": null
 }
}
